CREATE PROCEDURE [dbo].[sp_merge_menu_cfg_tables] AS /** ## Procedure Name       *[toast].[dbo].[sp_merge_menu_cfg_tables]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20251009      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0  	   declare @Params varchar(2000) = (select 'NoParams' as Params for json path)             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;          --declare @Store varchar(36) = (select  top 1 store_guid from toast.dbo.temp_cfg_menu_items)  		/*delete from toast.dbo.cfg_map_category_item         where store_guid = @Store; */         		 		merge toast.dbo.cfg_menu_items mi         using toast.dbo.temp_cfg_menu_items tmi         on mi.Store_GUID = tmi.Store_GUID         and mi.MultiLocationID = tmi.MultiLocationID         and mi.Sales_Cat_GUID = tmi.Sales_Cat_GUID         when matched then update set             Store_GUID = tmi.Store_GUID,             StoreNum = tmi.StoreNum,             Item_Name = tmi.Item_Name,             Item_POS_Name = tmi.Item_POS_Name,             Item_GUID = tmi.Item_GUID,             Item_Price = tmi.Item_Price,             Item_Pricing_Strategy = tmi.Item_Pricing_Strategy,             Item_Is_Deferred = tmi.Item_Is_Deferred,             Item_Is_Discountable = tmi.Item_Is_Discountable,             Sales_Cat_GUID = tmi.Sales_Cat_GUID,             Sales_Cat = tmi.Sales_Cat,             Item_PLU = tmi.Item_PLU,             Item_SKU = tmi.Item_SKU,             Modifier_Group_References = tmi.Modifier_Group_References,             Item_Kitchen_Name = tmi.Item_Kitchen_Name,             Prep_Stations = tmi.Prep_Stations,             Content_Advisories = tmi.Content_Advisories,             Guest_Count = tmi.Guest_Count,             MasterID = tmi.MasterID,             MultiLocationID = tmi.MultiLocationID,             Item_Is_Combo_Parent = tmi.Item_Is_Combo_Parent,             Item_Tags = tmi.Item_Tags         when not matched by target then             insert (Store_GUID, StoreNum, Item_Name, Item_POS_Name, Item_GUID, Item_Price, Item_Pricing_Strategy, Item_Is_Deferred, Item_Is_Discountable, Sales_Cat_GUID,                      Sales_Cat, Item_PLU, Item_SKU, Modifier_Group_References, Item_Kitchen_Name, Prep_Stations, Content_Advisories, Guest_Count, MasterID, MultiLocationID,                     Item_Is_Combo_Parent, Item_Tags)             values (tmi.Store_GUID, tmi.StoreNum, tmi.Item_Name, tmi.Item_POS_Name, tmi.Item_GUID, tmi.Item_Price, tmi.Item_Pricing_Strategy, tmi.Item_Is_Deferred,              tmi.Item_Is_Discountable, tmi.Sales_Cat_GUID, tmi.Sales_Cat, tmi.Item_PLU, tmi.Item_SKU, tmi.Modifier_Group_References, tmi.Item_Kitchen_Name,              tmi.Prep_Stations, tmi.Content_Advisories, tmi.Guest_Count, tmi.MasterID, tmi.MultiLocationID, tmi.Item_Is_Combo_Parent, tmi.Item_Tags);  		merge toast.dbo.cfg_map_category_item mi         using toast.dbo.temp_cfg_map_category_item tmi         on mi.Store_GUID = tmi.Store_GUID         and mi.Item_GUID = tmi.Item_GUID         and mi.Category_Guid = tmi.Category_Guid         when not matched by target then             insert (Store_GUID, Item_GUID, Category_Guid)             values (tmi.Store_GUID, tmi.Item_GUID, tmi.Category_Guid);          select *, ROW_NUMBER() over (partition by store_guid, item_guid, tag_guid order by store_guid, item_guid, tag_guid) as [rownum] 		into #DupeRem 		from toast.dbo.temp_cfg_map_item_tags 		order by store_guid, item_guid, tag_guid  		truncate table toast.dbo.temp_cfg_map_item_tags  		insert into toast.dbo.temp_cfg_map_item_tags (Store_GUID, Item_GUID, Tag_GUID, Item_PLU, MultiLocationId) 		select Store_GUID, Item_GUID, Tag_GUID, Item_PLU, MultiLocationId 		from #DupeRem 		where rownum = 1          drop table #duperem          /*delete from toast.dbo.cfg_map_item_tags         where store_guid = @Store; */                      merge toast.dbo.cfg_map_item_tags mi         using toast.dbo.temp_cfg_map_item_tags tmi         on mi.Store_GUID = tmi.Store_GUID         and mi.MultiLocationId = tmi.MultiLocationId         and mi.Tag_GUID = tmi.Tag_GUID         when matched then update set             Item_GUID = tmi.Item_GUID,             Item_PLU = tmi.Item_PLU         when not matched by target then             insert (Store_GUID, Item_GUID, Tag_GUID, Item_PLU, MultiLocationId)             values (tmi.Store_GUID, tmi.Item_GUID, tmi.Tag_GUID, tmi.Item_PLU, tmi.MultiLocationId);          /*delete from toast.dbo.cfg_map_menu_group_item         where store_guid = @Store; */          merge toast.dbo.cfg_map_menu_group_item mi         using toast.dbo.temp_cfg_map_menu_group_item tmi         on mi.store_guid = tmi.store_guid         and mi.menu_group_guid = tmi.menu_group_guid         and mi.item_guid = tmi.item_guid         when not matched by target then              insert (Store_GUID, Menu_Group_GUID, Item_GUID)             values (tmi.Store_GUID, tmi.Menu_Group_GUID, tmi.Item_GUID);          /*delete from toast.dbo.cfg_map_menu_menu_group         where StoreGUID = @Store; */          merge toast.dbo.cfg_map_menu_menu_group mi         using toast.dbo.temp_cfg_map_menu_menu_group tmi         on mi.StoreGUID = tmi.StoreGUID         and mi.MenuGUID = tmi.MenuGUID         and mi.MenuGroupGUID = tmi.MenuGroupGUID         when not matched by target then              insert (StoreGUID, MenuGUID, MenuGroupGUID)             values (tmi.StoreGUID, tmi.MenuGUID, tmi.MenuGroupGUID);          /*delete from toast.dbo.cfg_menu         where StoreGuid = @Store; */                      merge toast.dbo.cfg_menu mi         using toast.dbo.temp_cfg_menu tmi         on mi.StoreGuid = tmi.StoreGuid         and mi.MenuGuid = tmi.MenuGuid         when not matched by target then             insert(StoreGuid, MenuGuid, MenuName, MenuPosName, MenuDesc, MenuAval, MenuVisibility, MasterID, MultiLocationID)             values (tmi.StoreGuid, tmi.MenuGuid, tmi.MenuName, tmi.MenuPosName, tmi.MenuDesc, tmi.MenuAval, tmi.MenuVisibility, tmi.MasterID, tmi.MultiLocationID);          /*delete from toast.dbo.cfg_menu_groups         where StoreGuid = @Store; */ 		 		merge toast.dbo.cfg_menu_groups mi         using toast.dbo.temp_cfg_menu_groups tmi         on mi.StoreGuid = tmi.StoreGuid         and mi.MenuGroupGuid = tmi.MenuGroupGuid         and mi.MenuGroupName = tmi.MenuGroupName         when not matched by target then             insert (StoreGuid, MenuGroupGuid, MenuGroupName, MasterID, MultiLocationID)             values (tmi.StoreGuid, tmi.MenuGroupGuid, tmi.MenuGroupName, tmi.MasterID, tmi.MultiLocationID);          /*delete from toast.dbo.cfg_menu_items         where store_guid = @Store; */          /*delete from toast.dbo.cfg_tags         where StoreGuid = @Store; */ 		 		merge toast.dbo.cfg_tags mi         using toast.dbo.temp_cfg_tags tmi         on mi.Tag_GUID = tmi.Tag_GUID         and mi.StoreGuid = tmi.StoreGuid         when not matched by target then             insert (StoreGuid, Tag_GUID, Tag_Name, MasterID, MultiLocationID)             values (tmi.StoreGuid, tmi.Tag_GUID, tmi.Tag_Name, tmi.MasterID, tmi.MultiLocationID);          delete toast.dbo.temp_cfg_Sales_Cats         where Category_Guid is null         or Category_Name is null;          /*delete from toast.dbo.cfg_Sales_Cats         where Store_GUID = @Store; */                      merge toast.dbo.cfg_Sales_Cats mi         using toast.dbo.temp_cfg_Sales_Cats tmi         on mi.Store_GUID = tmi.Store_GUID         and mi.Category_Guid = tmi.Category_Guid         and mi.Category_Name = tmi.Category_Name         when not matched by target then             insert (Store_GUID, Category_Guid, Category_Name, MasterID, MultiLocationID)             values (tmi.Store_GUID, tmi.Category_Guid, tmi.Category_Name, tmi.MasterID, tmi.MultiLocationID);  		truncate table toast.dbo.temp_cfg_map_category_item 		truncate table toast.dbo.temp_cfg_map_item_tags 		truncate table toast.dbo.temp_cfg_map_menu_group_item 		truncate table toast.dbo.temp_cfg_map_menu_menu_group 		truncate table toast.dbo.temp_cfg_menu 		truncate table toast.dbo.temp_cfg_menu_groups 		truncate table toast.dbo.temp_cfg_menu_items 		truncate table toast.dbo.temp_cfg_tags 		truncate table toast.dbo.temp_cfg_Sales_Cats          update toast.dbo.cfg_tags set  			ConsolCatID =  				case 					when tag_name = '* Consolidated  Soups' then 9002 					when tag_name = '* Consolidated 2oz 4oz Dressings' then 9097 					when tag_name = '* Consolidated Beer' then 9007 					when tag_name = '* Consolidated Bulk GnG' then 9011 					when tag_name = '* Consolidated Catering' then 27 					when tag_name = '* Consolidated Desserts' then 9010 					when tag_name = '* Consolidated Extras and Misc' then 9012 					when tag_name = '* Consolidated Modifiers' then 9099 					when tag_name = '* Consolidated NA Bev' then 9006 					when tag_name = '* Consolidated Non Food' then 9014 					when tag_name = '* Consolidated Pasta and Mac' then 9003 					when tag_name = '* Consolidated Pizza' then 9001 					when tag_name = '* Consolidated Salads' then 9005 					when tag_name = '* Consolidated Sandwiches' then 9004 					when tag_name = '* Consolidated Sides' then 9009 					when tag_name = '* Consolidated Wine and Spirits' then 9008 					when tag_name = '* Consolidated Wraps' then 9017 				end                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END